import {VERSION,CATEGORIES,freshState,allQuestions,validateBank,validateBackup,stats,recordAnswer,selectPractice,createSession,createExam,finishSession,prepareExtra,readiness} from './engine.mjs';
import {openStore,readState,writeState} from './storage.mjs';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={plane:'M12 3v7L3 16v2l9-3v5l-3 2 3-1 3 1-3-2v-5l9 3v-2l-9-6V3',home:'m3 10 9-7 9 7v10H3Z M9 20v-7h6v7',grid:'M3 3h7v7H3Z M14 3h7v7h-7Z M3 14h7v7H3Z M14 14h7v7h-7Z',exam:'M6 3h12v18H6Z M9 7h6 M9 11h6 M9 15h4',chart:'M4 3v17h17 M8 15l4-5 4 2 5-7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',arrow:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',check:'m5 12 4 4 10-10',close:'m6 6 12 12 M18 6 6 18',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3Z M12 6v16',bookmark:'M6 3h12v19l-6-4-6 4Z',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z M8 12l3 3 5-6',layers:'m12 3 9 5-9 5-9-5Z M3 12l9 5 9-5 M3 16l9 5 9-5',tower:'M8 21h8 M10 10l-2 11 M14 10l2 11 M6 4h12l-2 6H8Z M12 1v3',wing:'M3 16c7-11 13-12 18-8-7 0-12 2-18 8Z M5 18h14',gear:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',gauge:'M4 19a10 10 0 1 1 16 0 M7 8l1 1 M12 5v2 M17 8l-1 1 M12 16l5-5 M5 19h14',cloud:'M6 18a4 4 0 1 1 1-8 6 6 0 0 1 11-1 4.5 4.5 0 1 1 1 9Z',balance:'M12 3v18 M7 21h10 M4 7h16 M6 7l-4 8h8Z M18 7l-4 8h8Z',compass:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20 M16 8l-3 5-5 3 3-5Z',route:'M5 3a2 2 0 1 0 0 4 2 2 0 0 0 0-4 M19 17a2 2 0 1 0 0 4 2 2 0 0 0 0-4 M5 7v7c0 6 10-4 14 3',heart:'M12 21C-5 10 7-2 12 6c5-8 17 4 0 15Z',target:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 11v2',refresh:'M20 8A9 9 0 0 0 4 6 M3 2v5h5 M4 16a9 9 0 0 0 16 2 M21 22v-5h-5',download:'M12 3v12m-5-5 5 5 5-5 M4 16v5h16v-5',external:'M13 3h8v8 M21 3l-11 11 M10 3H3v18h18v-7',flag:'M5 22V3c5-3 9 3 14 0v10c-5 3-9-3-14 0',calc:'M5 2h14v20H5Z M8 5h8v4H8Z M8 13h1 M15 13h1 M8 17h1 M15 17h1',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 1v2 M12 21v2 M1 12h2 M21 12h2 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 11v6 M12 7v1'};
const icon=(name,cls='')=>`<svg aria-hidden="true" class="${cls}" viewBox="0 0 24 24"><path d="${paths[name]||paths.book}"/></svg>`;
let base=[],state,db,view='today',category=null,filter='all',search='',count=20,mode='quiz',reviewResult=null,installPrompt=null,saveChain=Promise.resolve(),updateWaiting=null,busy=false;
const bank=()=>allQuestions(base,state),cat=id=>CATEGORIES.find(c=>c.id===id),name=id=>cat(id)?.name||id.replaceAll('-',' ');
const date=at=>new Date(at).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
const percent=v=>v===null?'—':`${v}%`;
function toast(message){const t=$('#toast');t.textContent=message;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',4500);}
function save(){saveChain=saveChain.catch(()=>{}).then(()=>writeState(db,state));saveChain.catch(()=>toast('Progress could not be saved. Export a backup before leaving.'));return saveChain;}
function applyTheme(){const dark=state.settings.theme==='dark'||(state.settings.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light';$('meta[name=theme-color]').content=dark?'#151a24':'#f5f6fa';}
const navs=[['today','Today','home'],['categories','Categories','grid'],['exams','Exams','exam'],['progress','Progress','chart']];
function activeNav(){if(['category','study','result','review'].includes(view))return state.session?.mode==='exam'?'exams':'categories';if(view==='boldmethod')return 'exams';return view;}
function shell(content){const active=activeNav();return `<aside class="sidebar"><div class="brand"><div class="brandmark">${icon('plane')}</div><div><div class="brand-name">Private Pilot</div><div class="brand-sub">Your study companion</div></div></div><div class="nav-label">FLIGHT DECK</div><nav aria-label="Main navigation">${navs.map(([id,label,i])=>`<button class="nav-item ${active===id?'active':''}" data-go="${id}" ${active===id?'aria-current="page"':''}>${icon(i)}${label}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="nav-item" data-go="boldmethod">${icon('external')}Boldmethod quizzes</button><button class="nav-item ${view==='settings'?'active':''}" data-go="settings">${icon('settings')}Settings & sources</button><div class="sidebar-note"><div class="flex">${icon('shield')}<strong>FAA Private Pilot · PAR</strong></div><p style="margin-top:9px">Original practice questions.<br>Your progress stays on this device.</p></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">Private Pilot Prep<span>/ ${esc(view==='category'?name(category):view==='study'?'Practice session':view==='boldmethod'?'Boldmethod':view.charAt(0).toUpperCase()+view.slice(1))}</span></div><div class="flex"><span id="offline-badge" class="tag"><span class="dot"></span>Checking offline readiness</span><button class="icon-btn" data-go="settings" aria-label="Settings">${icon('settings')}</button><div class="avatar">PAR</div></div></header><main id="main" tabindex="-1">${content}<p class="footer-note">Original FAA-based practice · FAA-S-ACS-6C · Content ${VERSION}<br>Practice guidance; no endorsement or pass guarantee.</p></main></div><nav class="mobile-nav" aria-label="Mobile navigation">${navs.map(([id,label,i])=>`<button class="${active===id?'active':''}" data-go="${id}" ${active===id?'aria-current="page"':''}>${icon(i)}${label}</button>`).join('')}</nav>`;}
function heading(title,sub,eyebrow='PRIVATE PILOT · AIRPLANE'){return `<div class="page-heading between"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><span class="date-label">${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</span></div>`;}
function metric(value,label,i,foot='',good=false){return `<div class="card metric"><div class="between"><span class="metric-icon">${icon(i)}</span></div><strong>${value}</strong><div class="label">${label}</div><div class="metric-foot ${good?'good':''}">${foot}</div></div>`;}
function categoryCard(c){const s=stats(state,c.id),total=bank().filter(q=>q.category===c.id).length,covered=new Set(state.attempts.filter(a=>a.category===c.id).map(a=>a.questionId)).size;return `<button class="card category-card" data-category="${c.id}" style="--cat:${c.color}"><div class="between"><div class="category-icon">${icon(c.icon)}</div><span class="arrow">${icon('arrow')}</span></div><h3>${c.name}</h3><p>${c.subtitle}</p><div class="progress-track"><span style="width:${Math.min(100,covered/total*100)}%"></span></div><div class="between"><span>${covered} / ${total} practiced</span><span>${percent(s.review)}</span></div></button>`;}
function boldCard(){return `<section class="card bold-card"><div class="between"><div class="bold-logo">bold<span>method</span></div><span class="tag">EXTRA PRACTICE</span></div><p>Explore the latest quizzes, then see the answers and explanations on Boldmethod.</p><div class="flex"><a class="btn secondary" href="https://www.boldmethod.com/topics/quiz/" target="_blank" rel="noopener noreferrer" data-bold-open="all">Open current quizzes ${icon('external')}</a><button class="icon-btn" data-go="boldmethod" aria-label="Boldmethod quiz journal">${icon('book')}</button></div><p class="small">Online · Publisher-hosted · Includes topics beyond PAR</p></section>`;}
function today(){
 const s=stats(state),covered=new Set(state.attempts.filter(a=>base.some(q=>q.id===a.questionId)).map(a=>a.questionId)).size,due=bank().filter(q=>state.reviews[q.id]?.due<=Date.now()).length,examAvg=state.exams.length?Math.round(state.exams.slice(-3).reduce((n,e)=>n+e.score,0)/Math.min(3,state.exams.length)):0,r=readiness(state),extra=Object.entries(state.extras);
 const focus=CATEGORIES.filter(c=>stats(state,c.id).recent.length).sort((a,b)=>(stats(state,a.id).review??0)-(stats(state,b.id).review??0)).slice(0,3);
 return heading('A little practice. A better pilot.','Your next step toward the private pilot written exam.')+`${state.session?`<div class="card pad between" style="margin-bottom:20px"><div><h3>You have a saved ${state.session.mode==='exam'?'mock exam':'study session'}</h3><p class="muted small">Question ${state.session.index+1} of ${state.session.questions.length} · Progress saved</p></div><button class="btn secondary" data-action="resume">Resume ${icon('arrow')}</button></div>`:''}<div class="dashboard-grid"><div><section class="hero"><div class="hero-content"><div class="eyebrow">YOUR DAILY FLIGHT PLAN</div><h2>Clear skies start<br>with preparation.</h2><p>A focused ${state.settings.daily}-question session, built around what you need to practice next.</p><button class="btn" data-action="daily">Start daily practice ${icon('arrow')}</button><div class="hero-meta"><span class="flex">${icon('clock')}About 15 minutes</span><span class="flex">${icon('refresh')}Adapts as you learn</span></div></div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 270 260"><path d="M-20 247 85 160l44 39 32-35 130 90" fill="#c5d9ee"/><path d="m40 269 145-100 110 82" fill="#bdd1e9"/><ellipse cx="206" cy="43" rx="45" ry="15" fill="#ffffff80"/><ellipse cx="53" cy="94" rx="33" ry="12" fill="#ffffff70"/><g transform="translate(128 97) rotate(-28)"><path d="M0-45c-6 0-8 6-8 14v27l-65 24v10L-8 14v29l-19 12v8L0 55l27 8v-8L8 43V14l65 16V20L8-4v-27c0-8-2-14-8-14Z" fill="#759cc8"/><path d="M0-40v94" stroke="#adc6e3" stroke-width="2"/></g><path d="m157 174-68 42" stroke="#94b1d3" stroke-width="2" stroke-dasharray="4 7"/></svg></div></section><div class="stats-grid">${metric(covered,'Questions practiced','book',`${Math.round(covered/base.length*100)}% of base bank covered`)}${metric(percent(s.first),'First-attempt accuracy','target',s.total?'Keep building understanding':'Your first answer counts')}${metric(due,'Ready for review','refresh',due?'A little review goes a long way':'You’re up to date',!due)}</div><div class="section-title between"><h2>Explore your subjects</h2><button class="link-button" data-go="categories">View all ${icon('arrow')}</button></div><div class="category-grid">${CATEGORIES.slice(0,6).map(categoryCard).join('')}</div></div><div class="side-column"><section class="card readiness"><div class="between"><h3>Exam readiness</h3><span class="tag blue">TARGET 90%</span></div><div class="ring" style="--value:${examAvg}"><div class="ring-inner"><strong>${state.exams.length?examAvg+'%':'—'}</strong><span>MOCK EXAM AVERAGE</span></div></div><div class="readiness-copy"><h3>${r.ready?'Practice target reached':state.exams.length?'Keep moving forward':'Let’s find your baseline'}</h3><p>${r.ready?'Three consecutive mock scores of 90% or higher.':`${r.scores.filter(x=>x>=90).length} of 3 recent mocks at 90%+`}</p><button class="link-button" data-go="exams">Take a mock exam ${icon('arrow')}</button></div></section><section class="card pad side-section"><div class="between"><h3>Your practice priorities</h3>${icon('target')}</div>${extra.length?extra.slice(0,3).map(([o,e])=>`<button class="practice-item" data-extra="${o}"><div class="category-icon" style="--cat:${cat(e.category)?.color||'#3478ed'}">${icon(cat(e.category)?.icon)}</div><div><h3>${esc(o.replaceAll('-',' '))}</h3><p>${e.ids.length} questions · ${e.review?'Includes repeat review':'Additional practice'}</p></div>${icon('arrow')}</button>`).join(''):focus.length?focus.map(c=>`<button class="practice-item" data-category="${c.id}"><div class="category-icon" style="--cat:${c.color}">${icon(c.icon)}</div><div><h3>${c.name}</h3><p>${percent(stats(state,c.id).review)} review accuracy</p></div>${icon('arrow')}</button>`).join(''):`<div class="empty" style="padding:24px 0 8px">${icon('compass')}<p>Start a session to discover<br>your strongest and weakest topics.</p></div>`}</section><div class="tip">${icon('shield')}<div><h3>Remember the answer, understand the why.</h3><p>Every question includes an explanation and an official source reference.</p></div></div>${boldCard()}</div></div>`;
}
function categories(){const matches=CATEGORIES.filter(c=>`${c.name} ${c.subtitle}`.toLowerCase().includes(search.toLowerCase()));return heading('A subject for every step.','Build confidence one category at a time.')+`<input class="search" id="category-search" type="search" placeholder="Search subjects…" aria-label="Search subjects" value="${esc(search)}"><div class="category-grid" style="margin-top:22px">${matches.map(categoryCard).join('')}</div>`;}
function categoryView(){const c=cat(category),s=stats(state,category),qs=selectPractice(bank(),state,{category,filter,count:'all',search});return `<div class="category-head"><button class="icon-btn" data-go="categories" aria-label="Back to categories">${icon('back')}</button><div class="category-icon" style="--cat:${c.color}">${icon(c.icon)}</div><div><h1>${c.name}</h1><p class="muted small">${c.subtitle}</p></div></div><div class="stats-grid">${metric(bank().filter(q=>q.category===category).length,'Available questions','book',`${state.generated.filter(q=>q.category===category).length} added variants`)}${metric(percent(s.first),'First-attempt accuracy','target')}${metric(percent(s.review),'Review accuracy','refresh')}</div><section class="card pad"><div class="between"><h2>Make it your session</h2><div class="segmented" role="group" aria-label="Study mode"><button data-mode="quiz" class="${mode==='quiz'?'active':''}">Quiz</button><button data-mode="memorize" class="${mode==='memorize'?'active':''}">Memorize</button></div></div><div class="toolbar"><select id="filter" aria-label="Question filter">${[['all','All questions'],['unseen','Unseen'],['missed','Missed'],['bookmarked','Bookmarked'],['added','Added practice']].map(([v,l])=>`<option value="${v}" ${filter===v?'selected':''}>${l}</option>`).join('')}</select><select id="count" aria-label="Session length">${[[10,'10 questions'],[20,'20 questions'],['all','Full selection']].map(([v,l])=>`<option value="${v}" ${count===v?'selected':''}>${l}</option>`).join('')}</select><button class="btn" data-action="category-start" ${qs.length?'':'disabled'}>${mode==='memorize'?'Start memorizing':'Start practice'} ${icon('arrow')}</button></div><p class="muted small">${qs.length} matching questions. ${mode==='memorize'?'Answers are visible. Viewing them does not change your scores.':'Choose an answer, then see the explanation and references.'}</p></section><div class="section-title between"><h2>Question bank</h2><span class="tag">${qs.length} QUESTIONS</span></div><input class="search" id="question-search" type="search" placeholder="Search questions or answer text…" aria-label="Search questions" value="${esc(search)}"><div class="question-list" style="margin-top:15px">${qs.length?qs.slice(0,60).map(q=>`<button class="card question-preview" data-question="${q.id}"><span class="tag ${q.kind==='generated'?'blue':''}">${q.kind==='generated'?'ADDED VARIANT':esc(q.objective.replaceAll('-',' '))}</span>${state.bookmarks.includes(q.id)?'<span class="tag blue">BOOKMARKED</span>':''}<p>${esc(q.prompt)}</p><span class="muted small">${esc(q.acs)} · ${state.reviews[q.id]?.lastCorrect===false?'Needs review':state.reviews[q.id]?'Practiced':'Unseen'}</span></button>`).join(''):`<div class="card empty">${icon('book')}<p>No questions match this selection.<br>Try a different filter or search.</p></div>`}${qs.length>60?`<p class="muted small">Showing 60 previews. Sessions use your full matching selection.</p>`:''}</div>`;}
function figure(q){return q.figure?`<figure class="figure"><button data-figure="${esc(q.figure.src)}" data-caption="${esc(q.figure.caption)}" aria-label="Enlarge ${esc(q.figure.caption)}"><img src="${esc(q.figure.src)}" alt="${esc(q.figure.alt)}" loading="lazy"></button><figcaption>${esc(q.figure.caption)} · Tap to enlarge</figcaption></figure>`:'';}
function explanation(q,selected){const selectedChoice=q.choices.find(c=>c.id===selected);return `<section class="feedback" aria-label="Answer explanation"><h3>${icon('book')}FAA-based explanation</h3><p>${esc(q.explanation)}</p>${selectedChoice&&selected!==q.answer?`<div class="rationale"><strong>Why your answer is incorrect</strong><p>${esc(selectedChoice.why)}</p></div>`:''}${q.memoryCue?`<p><strong>Remember:</strong> ${esc(q.memoryCue)}</p>`:''}${figure(q)}<div class="eyebrow muted" style="margin-top:19px">OFFICIAL REFERENCES</div>${q.references.map(r=>`<a class="reference" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ${icon('external')}<small>${esc(r.locator)} · ${esc(r.edition)}</small></a>`).join('')}<p class="muted small">${esc(q.acs)} · Source checked ${esc(q.references[0].verified)}<br>Explanation is a paraphrase of the cited material.</p></section>`;}
function study(){const s=state.session,q=s.questions[s.index],answered=s.recorded.includes(q.id),selected=s.answers[q.id],show=s.mode==='memorize'||(s.mode==='quiz'&&answered),c=cat(q.category);return `<div class="study-wrap"><div class="study-top between"><div><span class="eyebrow muted">${s.mode==='exam'?'MOCK EXAM':s.mode==='memorize'?'MEMORIZE':'PRACTICE'}</span><h1>${s.mode==='exam'?'Private Pilot · PAR':c.name}</h1></div><div class="flex">${s.mode==='exam'?'<span class="timer" id="timer" aria-label="Time remaining"></span>':''}<button class="icon-btn" data-action="calculator" aria-label="Calculator">${icon('calc')}</button><button class="icon-btn" data-action="pause" aria-label="Save and leave session">${icon('close')}</button></div></div><div class="study-progress"><div class="between small muted" style="margin-bottom:9px"><span>Question ${s.index+1} of ${s.questions.length}</span><span>${s.mode==='memorize'?'Answers visible':`${Object.keys(s.answers).length} answered`}</span></div><div class="progress-track"><span style="width:${(s.index+1)/s.questions.length*100}%"></span></div></div><section class="card question-card"><div class="question-meta"><span class="tag blue">${s.mode==='exam'?c.name:esc(q.objective.replaceAll('-',' '))}</span>${q.kind==='generated'?'<span class="tag">ADDED PRACTICE</span>':''}<button class="icon-btn" style="margin-left:auto;color:${state.bookmarks.includes(q.id)?'var(--blue)':'var(--muted)'}" data-action="bookmark" aria-label="${state.bookmarks.includes(q.id)?'Remove bookmark':'Bookmark question'}" aria-pressed="${state.bookmarks.includes(q.id)}">${icon('bookmark')}</button>${s.mode==='exam'?`<button class="icon-btn" data-action="flag" aria-label="Flag for review" aria-pressed="${s.flags.includes(q.id)}" style="color:${s.flags.includes(q.id)?'#dca33b':'var(--muted)'}">${icon('flag')}</button>`:''}</div><h2>${esc(q.prompt)}</h2>${q.figure&&!show?figure(q):''}<div class="answers" role="group" aria-label="Answer choices">${s.orders[q.id].map((id,i)=>{const choice=q.choices.find(c=>c.id===id);let css=selected===id?'selected':'';if(show&&id===q.answer)css='correct';if(show&&selected===id&&id!==q.answer)css='wrong';return `<button class="answer ${css}" data-choice="${id}" ${show?'aria-disabled="true"':''} aria-pressed="${selected===id}"><span class="answer-letter">${String.fromCharCode(65+i)}</span><span>${esc(choice.text)}</span>${show&&id===q.answer?'<span class="answer-status">Correct answer ✓</span>':show&&selected===id?'<span class="answer-status">Your answer ✕</span>':''}</button>`;}).join('')}</div>${show?`<div class="flex" role="status" style="margin-top:18px"><span class="tag ${s.mode==='memorize'?'blue':selected===q.answer?'green':'red'}">${s.mode==='memorize'?'MEMORIZE MODE':selected===q.answer?'CORRECT':'INCORRECT · CORRECT ANSWER SHOWN'}</span></div>${explanation(q,selected)}`:''}<div class="study-actions"><button class="btn quiet" data-action="previous" ${s.index?'':'disabled'}>${icon('back')}Previous</button>${s.mode==='quiz'&&!answered?`<button class="btn" data-action="check" ${selected?'':'disabled'}>Check answer ${icon('check')}</button>`:`<button class="btn" data-action="next">${s.index===s.questions.length-1?(s.mode==='exam'?'Review & submit':'Finish session'):'Next question'} ${icon('arrow')}</button>`}</div></section>${s.mode==='exam'?`<div class="navigator" aria-label="Exam question navigation">${s.questions.map((q,i)=>`<button class="${i===s.index?'current':''} ${s.answers[q.id]?'answered':''} ${s.flags.includes(q.id)?'flagged':''}" data-jump="${i}" aria-label="Question ${i+1}${s.flags.includes(q.id)?', flagged':''}${s.answers[q.id]?', answered':''}">${i+1}</button>`).join('')}</div><div class="between" style="margin-top:16px"><p class="muted small">Blue: answered · Gold underline: flagged</p><button class="link-button" data-action="submit-exam">Submit exam</button></div>`:''}</div>`;}
function result(){const r=reviewResult||state.lastResult;if(!r)return '<div class="empty">No session results yet.</div>';const missed=r.questions.filter(q=>r.answers[q.id]!==q.answer),extra=Object.entries(state.extras);return `<div class="study-wrap"><section class="card result-hero"><span class="tag ${r.mode==='exam'?(r.score>=70?'green':'red'):'blue'}">${r.mode==='memorize'?'MEMORIZATION COMPLETE':r.mode==='exam'?(r.score>=70?'PRACTICE PASS':'KEEP PRACTICING'):'SESSION COMPLETE'}</span><div class="result-score">${r.mode==='memorize'?icon('book'):r.score+'%'}</div><h2>${r.mode==='memorize'?'Another step forward.':r.score>=90?'Looking good, pilot.':r.score>=70?'You’re making progress.':'Let’s work on the tricky parts.'}</h2><p style="margin-top:10px">${r.mode==='memorize'?`${r.total} questions viewed. Scores and review schedules are unchanged.`:`${r.correct} of ${r.total} correct · ${Math.max(1,Math.round((r.finishedAt-r.startedAt)/60000))} minutes`}</p><div class="flex" style="justify-content:center;flex-wrap:wrap;margin-top:24px">${missed.length&&r.mode!=='memorize'?'<button class="btn" data-action="review-mistakes">Study these mistakes</button>':''}<button class="btn secondary" data-go="today">Back to Today</button></div></section>${r.mode!=='memorize'?`<section class="card pad"><h2>By category</h2><div class="breakdown">${CATEGORIES.filter(c=>r.questions.some(q=>q.category===c.id)).map(c=>{const qs=r.questions.filter(q=>q.category===c.id),pct=Math.round(qs.filter(q=>r.answers[q.id]===q.answer).length/qs.length*100);return `<div class="breakdown-row"><span>${c.name}</span><div class="progress-track"><span style="width:${pct}%"></span></div><strong>${pct}%</strong></div>`;}).join('')}</div></section><div class="section-title between"><h2>Answer review</h2><span class="tag">${missed.length} TO REVISIT</span></div><div class="question-list">${r.questions.map((q,i)=>`<button class="card question-preview" data-review-question="${i}"><span class="tag ${r.answers[q.id]===q.answer?'green':'red'}">${r.answers[q.id]===q.answer?'CORRECT':r.answers[q.id]?'INCORRECT':'UNANSWERED'}</span><p>${esc(q.prompt)}</p><span class="small muted">Tap for the correct answer, explanation, and sources.</span></button>`).join('')}</div>`:''}${extra.length?`<div class="section-title"><h2>Extra practice prepared for you</h2></div><section class="card pad">${extra.map(([o,e])=>`<button class="practice-item" data-extra="${o}">${icon('refresh')}<div><h3>${esc(o.replaceAll('-',' '))}</h3><p>${e.ids.length} questions · ${e.review?'Includes repeat review':'Fresh practice'}</p></div>${icon('arrow')}</button>`).join('')}</section>`:''}</div>`;}
function review(){const r=reviewResult||state.lastResult,q=r.questions[review.index],selected=r.answers[q.id];return `<div class="study-wrap"><div class="between study-top"><button class="btn quiet" data-go="result">${icon('back')}Results</button><span class="muted small">Answer ${review.index+1} of ${r.questions.length}</span></div><section class="card question-card"><span class="tag blue">${name(q.category)}</span><h2 style="margin-top:15px">${esc(q.prompt)}</h2><div class="answers">${r.orders[q.id].map((id,i)=>{const c=q.choices.find(c=>c.id===id);return `<div class="answer ${id===q.answer?'correct':id===selected?'wrong':''}"><span class="answer-letter">${String.fromCharCode(65+i)}</span><span>${esc(c.text)}</span>${id===q.answer?'<span class="answer-status">Correct answer ✓</span>':id===selected?'<span class="answer-status">Your answer ✕</span>':''}</div>`;}).join('')}</div>${!selected?'<p class="muted small" style="margin-top:15px">This question was unanswered.</p>':''}${explanation(q,selected)}<div class="between" style="margin-top:20px"><button class="btn quiet" data-review-prev ${review.index?'':'disabled'}>${icon('back')}Previous</button><button class="btn secondary" data-review-next ${review.index<r.questions.length-1?'':'disabled'}>Next${icon('arrow')}</button></div></section></div>`;}
review.index=0;
function exams(){const r=readiness(state);return heading('Practice for the real thing.','A full-length mock exam. A clear picture of where you stand.')+`<div class="dashboard-grid"><section class="card exam-card"><span class="tag blue">FAA PRIVATE PILOT AIRPLANE</span><h2>Your next mock exam</h2><p class="muted" style="font-size:13px">Practice working through a complete test, with a balanced mix of topics and shuffled answer choices.</p><div class="exam-spec"><div><strong>60</strong><span>Questions</span></div><div><strong>2 hours</strong><span>Time limit</span></div><div><strong>70%</strong><span>Passing score</span></div></div><button class="btn" data-action="new-exam">Start mock exam ${icon('arrow')}</button><p class="muted small" style="margin-top:18px">Explanations appear after submission. Your timer continues if you leave the app. Calculator available.</p><a class="small" href="https://www.faa.gov/training_testing/testing/acs/acs_knowledge_test_table.pdf" target="_blank" rel="noopener noreferrer">FAA exam timing reference ${icon('external')}</a></section><section class="card pad"><h3>The practice target</h3><div class="result-score" style="font-size:43px">90%+</div><p class="muted small">Aim for three consecutive mock exams at 90% or higher.</p><div class="flex" style="margin-top:20px">${[0,1,2].map(i=>`<span class="tag ${r.scores[i]>=90?'green':''}" style="padding:12px">${r.scores[i]!==undefined?r.scores[i]+'%':'—'}</span>`).join('')}</div><p class="muted small" style="margin-top:18px">${r.ready?'Target reached. Keep reviewing weaker categories.':'Also review categories below 80% on their latest 20 answers.'} This is practice guidance, not an endorsement.</p></section></div><div class="section-title"><h2>Exam history</h2></div><section class="card pad">${state.exams.length?state.exams.slice().reverse().map(e=>`<div class="history-row"><div class="history-score">${e.score}%</div><div><p>Private Pilot · PAR</p><span class="muted small">${date(e.finishedAt)} · ${e.correct}/60 correct</span></div><button class="link-button" data-exam-result="${e.id}">Review ${icon('arrow')}</button></div>`).join(''):'<div class="empty">'+icon('exam')+'<p>Your completed mock exams will appear here.</p></div>'}</section><div class="section-title"><h2>Beyond the question bank</h2></div>${boldCard()}`;}
function progress(){const s=stats(state),r=readiness(state),covered=new Set(state.attempts.filter(a=>base.some(q=>q.id===a.questionId)).map(a=>a.questionId)).size;return heading('See how far you’ve come.','Progress you can build on, one question at a time.')+`<div class="stats-grid">${metric(covered,'Base questions practiced','book',`${Math.round(covered/base.length*100)}% coverage`)}${metric(percent(s.first),'First-attempt accuracy','target',`${s.answered} unique questions`)}${metric(percent(s.review),'All-attempt accuracy','refresh',`${s.total} scored answers`)}</div><section class="card pad"><div class="between"><h2>Your subjects</h2><span class="tag">TARGET 80%+</span></div><div class="breakdown">${CATEGORIES.map(c=>{const a=stats(state,c.id),recent=a.recent.length?Math.round(a.recent.filter(x=>x.correct).length/a.recent.length*100):0;return `<div class="breakdown-row"><button class="link-button" style="text-align:left;color:var(--text)" data-category="${c.id}">${c.name}<span class="muted small" style="display:block">${a.recent.length}/20 recent answers · ${a.answered} unique practiced</span></button><div class="progress-track"><span style="width:${recent}%;background:${recent>=80&&a.recent.length===20?'var(--green)':'var(--blue)'}"></span></div><strong>${a.recent.length?recent+'%':'—'}</strong></div>`;}).join('')}</div></section><div class="dashboard-grid" style="margin-top:22px"><section class="card pad"><h2>A bank that grows with you</h2><div class="result-score" style="font-size:38px">${bank().length}</div><p class="muted small">${base.length} base questions · ${state.packs.length} imported · ${state.generated.length} added calculation variants.</p><p class="muted small" style="margin-top:10px">Wrong answers prepare focused extra practice. Conceptual topics reuse verified material once unseen questions run out.</p></section><section class="card pad"><h2>Your study record</h2><div class="breakdown"><div class="between small"><span>Completed mock exams</span><strong>${state.exams.length}</strong></div><div class="between small"><span>Bookmarked questions</span><strong>${state.bookmarks.length}</strong></div><div class="between small"><span>Practice target</span><strong>${r.ready?'Reached':'In progress'}</strong></div><div class="between small"><span>Boldmethod journal entries</span><strong>${(state.boldmethodHistory||[]).length}</strong></div></div><button class="btn secondary" style="margin-top:22px" data-action="export">${icon('download')}Export backup</button></section></div>`;}
function boldmethod(){return heading('A fresh aviation challenge.','Take quizzes on Boldmethod, then keep a personal record here.','BOLDMETHOD · PUBLISHER QUIZZES')+`${boldCard()}<section class="card pad" style="margin-top:20px"><h2>Choose your quiz</h2><p class="muted small" style="margin:10px 0 20px">These links open Boldmethod’s current quiz lists. The publisher provides the questions, correct answers, and explanations.</p><div class="flex" style="flex-wrap:wrap"><a class="btn secondary" href="https://www.boldmethod.com/topics/quiz-vfr/" target="_blank" rel="noopener noreferrer" data-bold-open="vfr">VFR quizzes ${icon('external')}</a><a class="btn quiet" href="https://www.boldmethod.com/topics/quiz-ifr/" target="_blank" rel="noopener noreferrer" data-bold-open="ifr">IFR quizzes ${icon('external')}</a><button class="btn" data-action="bold-log">Record a quiz result</button></div><p class="muted small" style="margin-top:18px">Publisher quizzes require an internet connection. Results are recorded by you; this app does not import or score Boldmethod questions.</p></section><div class="section-title between"><h2>Your quiz journal</h2><span class="tag">SAVED ON THIS DEVICE</span></div><section class="card pad">${state.boldmethodHistory?.length?state.boldmethodHistory.slice().reverse().map(e=>`<div class="history-row"><div class="history-score">${e.score!==null?e.score+'%':icon('external')}</div><div><p>${esc(e.title)}</p><span class="muted small">${date(e.at)} · ${e.score!==null?'Self-reported score':'Opened publisher quizzes'}</span><br><a class="small" href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">Open on Boldmethod ${icon('external')}</a></div></div>`).join(''):`<div class="empty">${icon('book')}<p>Your quiz activity will appear here.</p></div>`}</section><p class="muted small" style="margin-top:18px">No copied question bank. Automatic in-app import requires publisher permission or a licensed feed. App updates preserve this journal and your FAA practice history.</p>`;}
function settings(){return heading('Your personal flight deck.','Preferences, backups, and the sources behind your practice.')+`<section class="card pad settings-group"><h2>Preferences</h2><div class="settings-row"><div><h3>Appearance</h3><p>Choose what feels right for you.</p></div><select class="setting" id="theme" aria-label="Appearance">${[['system','Match device'],['light','Light'],['dark','Dark']].map(([v,l])=>`<option value="${v}" ${state.settings.theme===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="settings-row"><div><h3>Daily practice</h3><p>A focused session for your next visit.</p></div><select class="setting" id="daily" aria-label="Daily question count"><option value="10" ${state.settings.daily===10?'selected':''}>10 questions</option><option value="20" ${state.settings.daily===20?'selected':''}>20 questions</option></select></div><div class="settings-row"><div><h3>Add to your home screen</h3><p>${installPrompt?'Install this app on your device.':'On iPhone: Share → Add to Home Screen. On Android: browser menu → Install app.'}</p></div>${installPrompt?'<button class="btn secondary" data-action="install">Install app</button>':''}</div></section><section class="card pad settings-group"><h2>Your data</h2><div class="settings-row"><div><h3>Export a backup</h3><p>Includes history, bookmarks, variants, and saved sessions.</p></div><button class="btn secondary" data-action="export">${icon('download')}Export</button></div><div class="settings-row"><div><h3>Restore a backup</h3><p>Validated before replacing this device’s progress.</p></div><button class="btn quiet" data-action="import">Import backup</button></div><div class="settings-row"><div><h3>Add a verified question pack</h3><p>Import the documented JSON format with official citations.</p></div><button class="btn quiet" data-action="pack">Import pack</button></div><div class="settings-row"><div><h3>Storage</h3><p>Device-local IndexedDB. Clearing browser data removes local progress; keep a backup.</p></div><span class="tag">LOCAL</span></div><div class="settings-row"><div><h3>Content updates</h3><p>Checked on launch and periodically while open. Applied between sessions without deleting progress.</p></div><button class="btn secondary" data-action="updates">Check updates</button></div><div class="settings-row"><div><h3>Reset study progress</h3><p>Deletes this device’s study record. Export a backup first.</p></div><button class="btn danger" data-action="reset">Reset</button></div></section><section class="card pad source-list"><h2>Official source library</h2><a href="https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak" target="_blank" rel="noopener noreferrer">Pilot’s Handbook of Aeronautical Knowledge · FAA-H-8083-25C</a><a href="https://www.faa.gov/regulationspolicies/handbooksmanuals/aviation/faa-h-8083-28b-aviation-weather-handbook" target="_blank" rel="noopener noreferrer">Aviation Weather Handbook · FAA-H-8083-28B</a><a href="https://www.faa.gov/air_traffic/publications/" target="_blank" rel="noopener noreferrer">Aeronautical Information Manual</a><a href="https://www.ecfr.gov/current/title-14/chapter-I/subchapter-D/part-61" target="_blank" rel="noopener noreferrer">14 CFR Part 61 · Certification</a><a href="https://www.ecfr.gov/current/title-14/chapter-I/subchapter-F/part-91" target="_blank" rel="noopener noreferrer">14 CFR Part 91 · Operating rules</a><a href="https://www.faa.gov/training_testing/testing/acs/private_airplane_acs_6.pdf" target="_blank" rel="noopener noreferrer">Private Pilot ACS · FAA-S-ACS-6C</a><a href="https://www.faa.gov/training_testing/testing/supplements" target="_blank" rel="noopener noreferrer">Testing supplement · FAA-CT-8080-2H</a><p>These are original FAA-based practice questions. Explanations paraphrase cited material. Figures reproduce the identified FAA supplement figures. The active FAA examination bank is not publicly released. No instructor review or endorsement is claimed.</p><p>Individual questions show specific references, editions, and verification dates. Bank version ${VERSION}.</p></section><input class="file-input" id="backup-file" type="file" accept="application/json,.json"><input class="file-input" id="pack-file" type="file" accept="application/json,.json">`;}
function render(){applyTheme();const pages={today,categories,category:categoryView,study,result,review,exams,progress,boldmethod,settings};$('#app').innerHTML=shell((pages[view]||today)());refreshOfflineBadge();updateTimer();}
function go(next){view=next;if(next==='categories'){search='';category=null;}render();window.scrollTo({top:0});$('#main')?.focus({preventScroll:true});}
function dialog(html){const m=$('#modal');m.className='';m.innerHTML=html;const title=m.querySelector('h2');if(title){title.id='modal-title';m.setAttribute('aria-labelledby','modal-title');}m.showModal();}
async function confirmAction(title,text,action,label='Continue'){dialog(`<h2>${esc(title)}</h2><p>${esc(text)}</p><div class="dialog-actions"><button class="btn quiet" data-modal-close>Cancel</button><button class="btn" id="confirm-action">${esc(label)}</button></div>`);$('#confirm-action').onclick=async()=>{if(busy)return;busy=true;try{$('#modal').close();await action();}catch(e){toast(e.message);}finally{busy=false;}};}
async function start(questions,newMode='quiz',extraObjective=null){if(!questions.length){toast('No matching questions to practice.');return;}const begin=async()=>{if(extraObjective)delete state.extras[extraObjective];state.session=createSession(questions,newMode);reviewResult=null;await save();go('study');};if(state.session)await confirmAction('Replace your saved session?','Your scored answers are kept, but the unfinished session will be replaced.',begin,'Start new session');else await begin();}
async function complete(){const s=state.session;if(!s)return;const result=finishSession(state);if(s.mode==='exam')for(const q of result.questions.filter(q=>result.answers[q.id]!==q.answer))prepareExtra(state,bank(),q);reviewResult=null;await save();go('result');maybeApplyUpdate();}
function updateTimer(){const s=state?.session;if(!s||s.mode!=='exam')return;const left=Math.max(0,Math.ceil((s.deadline-Date.now())/1000)),target=$('#timer');if(target){target.textContent=`${Math.floor(left/3600)}:${String(Math.floor(left%3600/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;target.style.color=left<600?'var(--red)':'var(--blue)';}if(left===0&&!busy){busy=true;complete().finally(()=>{busy=false;toast('Time is up. Your saved answers were submitted.');});}}
function calcDialog(){let expr='';dialog(`<h2>Practice calculator</h2><p>Basic arithmetic. Follow the units and methods in each question.</p><div class="calc-output" id="calc-output">0</div><div class="calc-grid">${['C','(',')','÷','7','8','9','×','4','5','6','−','1','2','3','+','0','.','⌫','='].map(k=>`<button class="${/[+×÷−=]/.test(k)?'operator':''}" data-key="${k}">${k}</button>`).join('')}</div><div class="dialog-actions"><button class="btn quiet" data-modal-close>Done</button></div>`);$('#modal').querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{let k=b.dataset.key;if(k==='C')expr='';else if(k==='⌫')expr=expr.slice(0,-1);else if(k==='='){try{expr=String(calculate(expr));}catch{expr='Error';}}else{if(expr==='Error')expr='';if(expr.length<100)expr+=k;}$('#calc-output').textContent=expr||'0';});}
function calculate(expr){const tokens=expr.replaceAll('×','*').replaceAll('÷','/').replaceAll('−','-').match(/\d*\.?\d+|[()+\-*/]/g)||[];if(tokens.join('')!==expr.replaceAll('×','*').replaceAll('÷','/').replaceAll('−','-'))throw Error('Invalid');let p=0;const factor=()=>{if(tokens[p]==='-'){p++;return -factor();}if(tokens[p]==='+'){p++;return factor();}if(tokens[p]==='('){p++;let v=add();if(tokens[p++]!==')')throw Error('Parenthesis');return v;}let v=Number(tokens[p++]);if(!Number.isFinite(v))throw Error('Number');return v;};const multiply=()=>{let v=factor();while(['*','/'].includes(tokens[p])){let op=tokens[p++],n=factor();v=op==='*'?v*n:v/n;}return v;};const add=()=>{let v=multiply();while(['+','-'].includes(tokens[p])){let op=tokens[p++],n=multiply();v=op==='+'?v+n:v-n;}return v;};const value=add();if(p!==tokens.length||!Number.isFinite(value))throw Error('Expression');return Math.round(value*1e8)/1e8;}
async function boldLog(){dialog(`<h2>Record a Boldmethod quiz</h2><p>Keep the publisher link and your own result. This does not change FAA mock-exam scores.</p><div class="dialog-field"><label for="bold-title">Quiz title</label><input class="search" id="bold-title" maxlength="180" placeholder="e.g. Aircraft systems quiz"></div><div class="dialog-field"><label for="bold-url">Boldmethod quiz URL</label><input class="search" id="bold-url" type="url" placeholder="https://www.boldmethod.com/blog/quizzes/…"></div><div class="dialog-field"><label for="bold-score">Your score (%) — optional</label><input class="search" id="bold-score" type="number" min="0" max="100"></div><div class="dialog-actions"><button class="btn quiet" data-modal-close>Cancel</button><button class="btn" id="save-bold">Save result</button></div>`);$('#save-bold').onclick=async()=>{try{const title=$('#bold-title').value.trim();const u=new URL($('#bold-url').value);const raw=$('#bold-score').value;const score=raw===''?null:Number(raw);if(!title||u.protocol!=='https:'||!['www.boldmethod.com','boldmethod.com'].includes(u.hostname)||!u.pathname.startsWith('/blog/quizzes/')||(score!==null&&(!Number.isFinite(score)||score<0||score>100)))throw Error('Enter a title, a Boldmethod quiz URL, and a score from 0 to 100.');state.boldmethodHistory.push({title,url:u.href,score,at:Date.now()});await save();$('#modal').close();go('boldmethod');toast('Quiz result saved on this device.');}catch(e){toast(e.message);}};}
document.addEventListener('click',async event=>{const el=event.target.closest('button,a');if(!el)return;try{
 if(el.hasAttribute('data-modal-close')){$('#modal').close();return;}
 if(el.dataset.go){go(el.dataset.go);return;}if(el.dataset.category){category=el.dataset.category;filter='all';search='';go('category');return;}
 if(el.dataset.mode){mode=el.dataset.mode;render();return;}if(el.dataset.question){await start([bank().find(q=>q.id===el.dataset.question)],mode);return;}
 if(el.dataset.extra){const e=state.extras[el.dataset.extra];const qs=e.ids.map(id=>bank().find(q=>q.id===id)).filter(Boolean);await start(qs,'quiz',el.dataset.extra);return;}
 if(el.dataset.choice){const s=state.session;if(!s||s.mode==='memorize'||s.recorded.includes(s.questions[s.index].id))return;s.answers[s.questions[s.index].id]=el.dataset.choice;await save();render();return;}
 if(el.dataset.jump){state.session.index=Number(el.dataset.jump);await save();render();window.scrollTo({top:0});return;}
 if(el.dataset.figure){dialog(`<div class="between"><h2>${esc(el.dataset.caption)}</h2><button class="icon-btn" data-modal-close aria-label="Close figure">${icon('close')}</button></div><p>Pinch or use your browser zoom to inspect the figure.</p><img src="${esc(el.dataset.figure)}" alt="${esc(el.dataset.caption)}">`);$('#modal').className='figure-modal';return;}
 if(el.dataset.reviewQuestion){review.index=Number(el.dataset.reviewQuestion);go('review');return;}if(el.hasAttribute('data-review-prev')){review.index--;render();window.scrollTo({top:0});return;}if(el.hasAttribute('data-review-next')){review.index++;render();window.scrollTo({top:0});return;}
 if(el.dataset.examResult){reviewResult=state.exams.find(e=>e.id===el.dataset.examResult);go('result');return;}
 if(el.dataset.boldOpen){state.boldmethodHistory.push({title:el.dataset.boldOpen==='vfr'?'Opened VFR quizzes':el.dataset.boldOpen==='ifr'?'Opened IFR quizzes':'Opened current quizzes',url:el.href,score:null,at:Date.now()});await save();return;}
 const action=el.dataset.action,s=state.session,q=s?.questions[s.index];
 if(action==='daily')await start(selectPractice(bank(),state,{today:true,count:state.settings.daily}));
 if(action==='category-start')await start(selectPractice(bank(),state,{category,filter,count,search}),mode);
 if(action==='resume')go('study');if(action==='pause'){await save();go('today');toast('Session saved. Resume whenever you’re ready.');}
 if(action==='bookmark'){state.bookmarks=state.bookmarks.includes(q.id)?state.bookmarks.filter(id=>id!==q.id):[...state.bookmarks,q.id];await save();render();}
 if(action==='flag'){s.flags=s.flags.includes(q.id)?s.flags.filter(id=>id!==q.id):[...s.flags,q.id];await save();render();}
 if(action==='check'&&s.answers[q.id]&&!s.recorded.includes(q.id)){const correct=recordAnswer(state,q,s.answers[q.id]);s.recorded.push(q.id);if(!correct)prepareExtra(state,bank(),q);await save();render();$('.feedback')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});}
 if(action==='previous'&&s.index>0){s.index--;await save();render();window.scrollTo({top:0});}
 if(action==='next'){if(s.index<s.questions.length-1){s.index++;await save();render();window.scrollTo({top:0});}else if(s.mode==='exam')await confirmAction('Submit your mock exam?',`${Object.keys(s.answers).length} of 60 questions answered. Unanswered questions count as incorrect. You can review answers after submission.`,complete,'Submit exam');else if(s.mode==='quiz'&&s.recorded.length<s.questions.length)await confirmAction('Finish this session?',`${s.questions.length-s.recorded.length} questions are unchecked. They will count as unanswered in this session result.`,complete,'Finish session');else await complete();}
 if(action==='submit-exam')await confirmAction('Submit your mock exam?',`${Object.keys(s.answers).length} of 60 questions answered. Unanswered questions count as incorrect.`,complete,'Submit exam');
 if(action==='new-exam'){const begin=async()=>{state.session=createExam([...base,...state.packs]);await save();go('study');};if(s)await confirmAction('Replace your saved session?','Your scored answers are kept; your unfinished session will be replaced.',begin,'Start exam');else await begin();}
 if(action==='review-mistakes'){const r=reviewResult||state.lastResult;await start(r.questions.filter(q=>r.answers[q.id]!==q.answer));}
 if(action==='calculator')calcDialog();if(action==='bold-log')await boldLog();
 if(action==='export'){await save();const blob=new Blob([JSON.stringify({format:'private-pilot-prep',version:1,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`pilot-prep-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported.');}
 if(action==='import')$('#backup-file').click();if(action==='pack')$('#pack-file').click();
 if(action==='reset')await confirmAction('Reset all study progress?','This deletes local answers, exam history, bookmarks, generated questions, imported packs, saved sessions, and the Boldmethod journal. It cannot be undone without a backup.',async()=>{state=freshState();state.boldmethodHistory=[];await save();go('today');toast('Study progress reset.');},'Reset progress');
 if(action==='install'){await installPrompt.prompt();installPrompt=null;render();}
 if(action==='updates'){await checkUpdates(true);} 
 }catch(e){toast(e.message||'Something went wrong. Your saved progress is still available.');}});
document.addEventListener('input',e=>{if(['category-search','question-search'].includes(e.target.id)){const id=e.target.id,value=e.target.value,pos=e.target.selectionStart;search=value;render();const field=$('#'+id);field.focus();if(field.type!=='search')field.setSelectionRange(pos,pos);}});
document.addEventListener('change',async e=>{try{const id=e.target.id;if(id==='filter'){filter=e.target.value;render();}if(id==='count'){count=e.target.value==='all'?'all':Number(e.target.value);render();}if(id==='theme'){state.settings.theme=e.target.value;await save();render();}if(id==='daily'){state.settings.daily=Number(e.target.value);await save();render();}
 if(['backup-file','pack-file'].includes(id)){const file=e.target.files[0];if(!file)return;if(file.size>30*1024*1024)throw Error('File is too large. Limit: 30 MB.');const data=JSON.parse(await file.text());e.target.value='';if(id==='backup-file'){const incoming=validateBackup(data);const baseIds=new Set(base.map(q=>q.id));if([...incoming.generated,...incoming.packs].some(q=>baseIds.has(q.id)))throw Error('Backup contains IDs that collide with the base bank.');incoming.boldmethodHistory??=[];await confirmAction('Replace this device’s progress?','The backup has been validated. Your current local record will be replaced. Export it first if you need both.',async()=>{state=incoming;reviewResult=null;await save();go(state.session?'study':'today');toast('Backup restored.');},'Restore backup');}else{if(data.format!=='private-pilot-prep-pack'||data.version!==1||!Array.isArray(data.questions))throw Error('Unsupported question pack. See the supplied format guide.');validateBank(data.questions);const ids=new Set(bank().map(q=>q.id)),prompts=new Set(bank().map(q=>q.prompt));if(data.questions.some(q=>ids.has(q.id)||prompts.has(q.prompt)))throw Error('Pack contains existing question IDs or prompts.');await confirmAction('Add this question pack?',`${data.questions.length} questions passed structural checks. Only import material you have independently verified; this check cannot certify factual accuracy.`,async()=>{state.packs.push(...data.questions.map(q=>({...q,kind:'authored'})));await save();render();toast('Question pack added.');},'Add questions');}}}catch(error){toast(error.message);}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>state&&applyTheme());
let offlineReady=false;
function refreshOfflineBadge(){const el=$('#offline-badge');if(el){el.innerHTML=`<span class="dot"></span>${offlineReady?(navigator.onLine?'Ready offline':'Offline · saved on device'):(navigator.onLine?'Preparing offline cache':'Offline cache unavailable')}`;el.className='tag '+(offlineReady?'green':'');}}
window.addEventListener('online',()=>{refreshOfflineBadge();checkUpdates();});window.addEventListener('offline',refreshOfflineBadge);
async function setupOffline(){if(!('serviceWorker'in navigator)){toast('Offline installation is unavailable in this browser.');return;}try{const reg=await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});const check=()=>{if(reg.waiting){updateWaiting=reg.waiting;maybeApplyUpdate();}};check();reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed')check();});});await navigator.serviceWorker.ready;const cache=await caches.open('pilot-prep-'+VERSION);offlineReady=!!await cache.match('./offline-ready');refreshOfflineBadge();navigator.serviceWorker.addEventListener('message',e=>{if(e.data==='offline-ready'){offlineReady=true;refreshOfflineBadge();}});navigator.serviceWorker.addEventListener('controllerchange',()=>{if(window.hadController)location.reload();window.hadController=true;});window.hadController=!!navigator.serviceWorker.controller;}catch(e){console.warn('Offline cache',e);toast('Offline cache could not finish. You can still study online.');}}
async function maybeApplyUpdate(){if(updateWaiting&&!state.session){await save();updateWaiting.postMessage('activate-update');updateWaiting=null;}}
async function checkUpdates(explicit=false){if(!navigator.onLine){if(explicit)toast('Reconnect to check for updates. Your offline questions are available.');return;}try{const reg=await navigator.serviceWorker.getRegistration();await reg?.update();if(reg?.waiting){updateWaiting=reg.waiting;if(state.session){if(explicit)toast('Update ready. It will apply after your saved session finishes.');}else await maybeApplyUpdate();}else if(explicit)toast('App content is up to date. Your history is preserved.');}catch{if(explicit)toast('Update check unavailable. Your saved content and progress are unchanged.');}}
setInterval(()=>{updateTimer();},1000);setInterval(()=>{if(!document.hidden)checkUpdates();},60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){updateTimer();checkUpdates();}});
async function init(){try{db=await openStore();state=await readState(db)||freshState();state.boldmethodHistory??=[];base=(await Promise.all(['bank-a.json','bank-b.json'].map(async f=>{const r=await fetch('./data/'+f);if(!r.ok)throw Error('Question content unavailable.');return r.json();}))).flat();validateBank(base);state.contentVersion=VERSION;await save();view=state.session?'study':'today';render();setupOffline();updateTimer();}catch(e){$('#app').innerHTML=`<div class="loading"><h1>Unable to open your flight deck</h1><p>${esc(e.message)}</p><button class="btn" id="retry">Try again</button><p>Your existing browser data has not been deleted.</p></div>`;$('#retry').onclick=()=>location.reload();console.error(e);}}
init();
